class Data(Task):

    def output(self):
        return LocalTarget("data/data.csv")

    def run(self):
        df = datasets.load_boston()
        df = pd.DataFrame(df.data, columns=df.feature_names)
        df["target"] = df["target"]
        df.to_csv(self.output().path, index=False)


class Train(Task):

    def requires(self):
        return Data()

    def output(self):
        return LocalTarget("data/train.csv")

    def run(self):
        df = pd.read_csv(self.input().path)
        df.to_csv(self.output().path, index=False)


class Test(Task):

    def requires(self):
        return Data()

    def output(self):
        return LocalTarget("data/test.csv")

    def run(self):
        df = pd.read_csv(self.input().path)
        df.to_csv(self.output().path, index=False)


